/**
 * # Safety
 *
 * `params` must point to `paramCount` valid entries, each holding
 * NUL-terminated UTF-16 strings.
 */
RFC_CONNECTION_HANDLE RfcOpenConnection(const RFC_CONNECTION_PARAMETER *params,
                                        unsigned int paramCount,
                                        RFC_ERROR_INFO *error);

/**
 * # Safety
 *
 * `handle` must be one `RfcOpenConnection` returned and not yet closed.
 */
RFC_RC RfcCloseConnection(RFC_CONNECTION_HANDLE handle,
                          RFC_ERROR_INFO *error);

/**
 * Wakes the call another thread is waiting on, on `handle`, by shutting its
 * socket down; that call then fails as a communication failure and the
 * conversation is over. **Not part of SAP's API** -- an erpl extension.
 *
 * For a caller that has given up on a call altogether (a Ruby `Thread#kill`
 * or `Timeout`, a Go context cancellation) when the peer may have vanished:
 * `RfcCancel` needs a peer that answers, and neither SAP's library nor this
 * one sets keepalive or a read timeout on an established call (PRO-12a), so
 * nothing else ends that wait. `RfcCloseConnection` does not either: in SAP's
 * library it leaves the waiting call to finish (CAN-6), and so does this one.
 * Usable before or after `RfcCloseConnection` on the same handle.
 *
 * `RFC_OK` when a call was in flight and is being woken; `RFC_ILLEGAL_STATE`
 * when none was.
 *
 * # Safety
 *
 * `error` must be writable or null.
 */
RFC_RC ErplAbortCall(RFC_CONNECTION_HANDLE handle,
                     RFC_ERROR_INFO *error);

/**
 * Cancels the call in flight on `handle`, from another thread (spec CAN-1).
 *
 * Measured against SAP's library (`oracle/abi_after_message.c`, CANCEL):
 * `RfcCancel` returns `RFC_OK`, the blocked `RfcInvoke` returns
 * `RFC_CANCELED` (7, group 4) well before the call would have finished, and
 * the handle is then invalid to everything, close included (CAN-2). With no
 * call in flight it is refused as `RFC_ILLEGAL_STATE` and changes nothing.
 *
 * # Safety
 *
 * `error` must be writable or null.
 */
RFC_RC RfcCancel(RFC_CONNECTION_HANDLE handle,
                 RFC_ERROR_INFO *error);

/**
 * Whether `handle` is a connection this library still answers to.
 *
 * Measured against SAP's library (`oracle/abi_after_message.c`): a live
 * handle gives `1` and `RFC_OK`; a closed or invalidated one -- after
 * `RfcCloseConnection`, or after a MESSAGE-raised failure -- gives `0` and
 * `RFC_INVALID_HANDLE`. A registration counts as a live handle.
 *
 * # Safety
 *
 * `is_valid` must be writable or null; `error` must be writable or null.
 */
RFC_RC RfcIsConnectionHandleValid(RFC_CONNECTION_HANDLE handle,
                                  int *is_valid,
                                  RFC_ERROR_INFO *error);

/**
 * # Safety
 *
 * As `RfcCloseConnection`.
 */
RFC_RC RfcPing(RFC_CONNECTION_HANDLE handle,
               RFC_ERROR_INFO *error);

/**
 * # Safety
 *
 * `attributes` must point to a writable `RFC_ATTRIBUTES`.
 */
RFC_RC RfcGetConnectionAttributes(RFC_CONNECTION_HANDLE handle,
                                  RFC_ATTRIBUTES *attributes,
                                  RFC_ERROR_INFO *error);

/**
 * Renders a return code. Consumers put this straight into user-facing errors.
 *
 * # Safety
 *
 * The returned pointer is valid for the lifetime of the process: it points at
 * a static table, exactly as SAP's does, because callers keep it.
 * Reports this library's version, where the SDK reports its own.
 *
 * # Safety
 *
 * The three out-pointers, where non-null, must be writable.
 *
 * A consumer uses this as a liveness check -- `erpl-rev` refuses to start if it
 * returns nothing -- so a stub returning null is not a harmless gap: it stops
 * the program before anything else is tried. The returned string is static and
 * the caller must not free it, which is the SDK's contract too.
 *
 * The numbers are erpl-proto's own. Reporting SAP's would be a lie a consumer
 * could act on: something that branches on the SDK version to decide what is
 * available would be told about a library that is not this one.
 */
const SAP_UC *RfcGetVersion(unsigned int *majorVersion,
                            unsigned int *minorVersion,
                            unsigned int *patchLevel);

const SAP_UC *RfcGetRcAsString(RFC_RC rc);

/**
 * Renders a direction, for the same reason.
 */
const SAP_UC *RfcGetDirectionAsString(RFC_DIRECTION direction);

/**
 * Renders an ABAP type name.
 */
const SAP_UC *RfcGetTypeAsString(RFCTYPE ty);

/**
 * Accepted and ignored: tracing here is `erpl-proto-proxy`, which sees the whole
 * conversation rather than one side's idea of it. Returning `RFC_OK` keeps a
 * consumer that always configures tracing working; returning an error would
 * fail a program that was only trying to be tidy.
 */
RFC_RC RfcSetTraceDir(const SAP_UC *_dir,
                      RFC_ERROR_INFO *error);

RFC_RC RfcSetMaximumTraceFileSize(unsigned int _size,
                                  RFC_ERROR_INFO *error);

RFC_RC RfcSetMaximumStoredTraceFiles(unsigned int _count,
                                     RFC_ERROR_INFO *error);

/**
 * There is no ini file: connection settings come from the caller. Reporting
 * success is honest here — there is nothing to reload, and nothing depends on
 * one having been read.
 */
RFC_RC RfcReloadIniFile(RFC_ERROR_INFO *error);

RFC_RC RfcSetIniPath(const SAP_UC *_path,
                     RFC_ERROR_INFO *error);

/**
 * # Safety
 *
 * `tid` must point to `RFC_TID_LN + 1` characters.
 */
RFC_RC RfcGetTransactionID(RFC_CONNECTION_HANDLE connection,
                           SAP_UC *tid,
                           RFC_ERROR_INFO *error);

/**
 * # Safety
 *
 * `tid` must be a NUL-terminated UTF-16 transaction ID.
 */
RFC_RC RfcConfirmTransactionID(RFC_CONNECTION_HANDLE connection,
                               const SAP_UC *tid,
                               RFC_ERROR_INFO *error);

/**
 * # Safety
 *
 * `tid` must be a NUL-terminated UTF-16 transaction ID, or null.
 * `queueName` must be NUL-terminated UTF-16, or null for tRFC.
 */
RFC_TRANSACTION_HANDLE RfcCreateTransaction(RFC_CONNECTION_HANDLE connection,
                                            const SAP_UC *tid,
                                            const SAP_UC *queueName,
                                            RFC_ERROR_INFO *error);

/**
 * # Safety
 *
 * Both handles must be ones this library issued.
 */
RFC_RC RfcInvokeInTransaction(RFC_TRANSACTION_HANDLE transaction,
                              RFC_FUNCTION_HANDLE function,
                              RFC_ERROR_INFO *error);

/**
 * # Safety
 *
 * `transaction` must be one `RfcCreateTransaction` returned.
 */
RFC_RC RfcSubmitTransaction(RFC_TRANSACTION_HANDLE transaction,
                            RFC_ERROR_INFO *error);

/**
 * # Safety
 *
 * As `RfcSubmitTransaction`.
 */
RFC_RC RfcConfirmTransaction(RFC_TRANSACTION_HANDLE transaction,
                             RFC_ERROR_INFO *error);

/**
 * # Safety
 *
 * As `RfcSubmitTransaction`.
 */
RFC_RC RfcDestroyTransaction(RFC_TRANSACTION_HANDLE transaction,
                             RFC_ERROR_INFO *error);

