/**
 * Frees a function description and its per-parameter side tables (memory 2).
 *
 * The shared type layouts it referenced are left intact -- they belong to the
 * type table and are used by other functions -- and are freed only by
 * `RfcDestroyTypeDesc`. Removing an unknown handle is not an error; the C API
 * treats destroy as idempotent.
 *
 * # Safety
 *
 * `error` must be null or a writable `RFC_ERROR_INFO`.
 */
RFC_RC RfcDestroyFunctionDesc(RFC_FUNCTION_DESC_HANDLE desc,
                              RFC_ERROR_INFO *error);

/**
 * Frees a structure/table type descriptor (memory 2).
 *
 * # Safety
 *
 * `error` must be null or a writable `RFC_ERROR_INFO`.
 */
RFC_RC RfcDestroyTypeDesc(RFC_TYPE_DESC_HANDLE ty,
                          RFC_ERROR_INFO *error);

/**
 * # Safety
 *
 * `funcName` must be a NUL-terminated UTF-16 string.
 */
